# Server: trial data in a reactive value, results recomputed on "Update
# recommendation" (and once on start-up), with a note when settings or
# data have changed since.

decision_icons <- c(D = "arrow-down-circle", S = "arrow-right-circle",
                    E = "arrow-up-circle", Stop = "x-octagon")

#' Fit the design to the trial data and project the pathway
#'
#' @param settings A list of the sidebar settings (see `app_server()`).
#' @param trial Canonical trial data.
#' @return A list with `problems` (character, empty when fitted) and, when
#'   fitted, `design`, `data` (every patient), `pathway` (evaluable patients
#'   only) and the settings used.
run_model <- function(settings, trial) {
  s <- settings
  skeleton <- skeleton_from_settings(s$prior_type, s$target, s$halfwidth,
                                     s$prior_mtd, s$num_doses,
                                     s$skeleton_text)
  variance <- variance_from_settings(s$variance_type, s$variance,
                                     skeleton$skeleton, s$target)
  stop_prior <- stopping_prior(s$stop_default_prior, s$stop_prior_mean,
                               s$stop_prior_ess, s$target)
  problems <- c(
    validate_settings(s$obswin, s$day_of_assessment,
                      if (isTRUE(s$stop_on)) s$stop_n_min else 0),
    skeleton$problem,
    variance$problem,
    if (isTRUE(s$stop_on)) stop_prior$problem
  )
  if (length(problems) == 0) {
    problems <- validate_trial_data(trial, s$num_doses, s$day_of_assessment,
                                    s$obswin)
  }
  if (length(problems)) {
    return(list(problems = problems))
  }

  tryCatch({
    design <- build_design(
      skeleton = skeleton$skeleton, target = s$target, obswin = s$obswin,
      variance = variance$variance, no_skip_esc = s$no_skip_esc,
      no_skip_deesc = s$no_skip_deesc,
      global_coherence = s$global_coherence,
      stop_confidence = if (isTRUE(s$stop_on)) s$stop_confidence,
      stop_n_min = s$stop_n_min, stop_a = stop_prior$a,
      stop_b = stop_prior$b
    )
    data <- normalise_trial_data(trial, s$day_of_assessment, s$obswin)
    pathway <- dtp_pathway(design$parent, evaluable_patients(data),
                           s$day_of_assessment, s$obswin)
    list(problems = character(), design = design, data = data,
         pathway = pathway, skeleton = skeleton$skeleton,
         variance = variance$variance, settings = s)
  }, error = function(e) {
    list(problems = paste("The model could not be fitted:",
                          conditionMessage(e)))
  })
}

summary_boxes <- function(result) {
  p <- result$pathway
  msg <- recommendation_text(p)
  now <- msg$decision
  colour <- dtp_colours$decision[[now]]
  first <- p$runs[1, ]
  later <- p$runs[-1, , drop = FALSE]
  # As the pathway: evaluable patients only.
  in_model <- evaluable_patients(result$data)
  pending <- sum(in_model$monitored & in_model$weight < 1)
  excluded <- nrow(result$data) - nrow(in_model)

  # A slim icon column leaves room for the text in narrow tiles.
  tile_layout <- bslib::showcase_left_center(width = 0.25)
  bslib::layout_columns(
    fill = FALSE,
    bslib::value_box(
      showcase_layout = tile_layout,
      title = sprintf("Day %d", p$day_of_assessment),
      value = if (now == "Stop") "Stop the trial" else
        sprintf("Dose %d", first$dose),
      showcase = bsicons::bs_icon(decision_icons[[now]]),
      theme = bslib::value_box_theme(bg = colour, fg = text_on(colour)),
      htmltools::p(if (now == "Stop") "The lowest dose is too toxic." else
        paste0(toupper(substring(decision_labels[[now]], 1, 1)),
               substring(tolower(decision_labels[[now]]), 2),
               sprintf(" (current dose %d)", p$current_dose)))
    ),
    bslib::value_box(
      showcase_layout = tile_layout,
      title = "If no new DLTs",
      value = if (nrow(later)) sprintf("Day %d", later$from_day[1]) else
        "None",
      # Neutral tile; the icon shows the next decision in its colour, as on
      # the pathway bar.
      showcase = if (nrow(later)) {
        bsicons::bs_icon(
          decision_icons[[later$decision[1]]],
          color = dtp_colours$decision[[later$decision[1]]]
        )
      } else {
        bsicons::bs_icon("calendar-check")
      },
      theme = "light",
      # Every later change, so nothing is lost when there are several.
      if (nrow(later)) {
        lapply(seq_len(nrow(later)), function(i) {
          what <- sub("dose level", "dose",
                      describe_dose(later$dose[i], p$current_dose))
          htmltools::p(class = "mb-0", if (i == 1) {
            paste0(toupper(substring(what, 1, 1)), substring(what, 2))
          } else {
            sprintf("Then from day %d: %s", later$from_day[i], what)
          })
        })
      } else {
        htmltools::p("Recommendation holds")
      }
    ),
    bslib::value_box(
      showcase_layout = tile_layout,
      title = "Follow-up completes",
      value = if (p$complete_day == p$day_of_assessment) "Complete" else
        sprintf("Day %d", p$complete_day),
      showcase = bsicons::bs_icon("hourglass-split"),
      theme = "light",
      htmltools::p(class = "mb-0",
                   sprintf("%d patient%s in follow-up", pending,
                           if (pending == 1) "" else "s")),
      if (excluded) {
        htmltools::p(sprintf("%d not evaluable, not in the model", excluded))
      }
    )
  )
}

problems_alert <- function(problems, title) {
  htmltools::div(
    class = "alert alert-warning mb-0", role = "alert",
    htmltools::strong(title),
    htmltools::tags$ul(class = "mb-0",
                       lapply(problems, htmltools::tags$li))
  )
}

#' The app's server
app_server <- function(input, output, session) {
  trial <- shiny::reactiveVal(canonical_trial(example_trial_data()))
  set_trial <- function(x) {
    x <- canonical_trial(x)
    if (!identical(x, trial())) trial(x)
  }

  settings <- shiny::reactive({
    ids <- c("num_doses", "target", "obswin", "prior_type", "prior_mtd",
             "halfwidth", "skeleton_text", "variance_type", "variance",
             "no_skip_esc",
             "no_skip_deesc", "global_coherence", "stop_on",
             "stop_confidence", "stop_n_min", "stop_default_prior",
             "stop_prior_mean", "stop_prior_ess", "day_of_assessment")
    stats::setNames(lapply(ids, function(id) input[[id]]), ids)
  })

  # The half-width defaults to a quarter of the target.
  shiny::observeEvent(input$target, ignoreInit = TRUE, {
    shiny::updateNumericInput(session, "halfwidth",
                              value = input$target / 4)
  })

  # The MTD guess cannot exceed the number of doses (legacy kept the old
  # maximum until the prior type was switched).
  shiny::observeEvent(input$num_doses, {
    shiny::updateSliderInput(session, "prior_mtd", max = input$num_doses,
                             value = min(input$prior_mtd, input$num_doses))
  })

  # --- Trial data --------------------------------------------------------
  grid_view <- shiny::reactive({
    shiny::req(input$obswin, input$day_of_assessment)
    grid_frame(trial(), input$day_of_assessment, input$obswin)
  })
  output$grid <- rhandsontable::renderRHandsontable({
    render_grid(grid_view(), input$num_doses)
  })
  shiny::observeEvent(input$grid, {
    set_trial(trial_from_grid(rhandsontable::hot_to_r(input$grid)))
  })
  shiny::observeEvent(input$add_patient, {
    set_trial(add_patient(trial(), input$day_of_assessment))
  })
  shiny::observeEvent(input$load_example, {
    set_trial(example_trial_data())
  })
  shiny::observeEvent(input$upload, {
    loaded <- tryCatch(
      read_trial_file(input$upload$datapath, input$upload$name,
                      obswin = input$obswin),
      error = function(e) e
    )
    if (inherits(loaded, "error")) {
      bslib::show_toast(bslib::toast(
        conditionMessage(loaded), header = "Could not read the file",
        type = "danger"
      ))
    } else {
      set_trial(loaded)
      bslib::show_toast(bslib::toast(
        sprintf("%d patients loaded from %s.", nrow(loaded),
                input$upload$name),
        type = "success"
      ))
    }
  })
  output$data_problems <- shiny::renderUI({
    shiny::req(input$obswin, input$day_of_assessment, input$num_doses)
    problems <- validate_trial_data(trial(), input$num_doses,
                                    input$day_of_assessment, input$obswin)
    if (length(problems)) {
      problems_alert(problems, "Please check the trial data:")
    }
  })
  write_csv <- function(x, file) utils::write.csv(x, file, row.names = FALSE,
                                                  na = "")
  output$download_data <- shiny::downloadHandler(
    filename = function() sprintf("dtp-titecrm-data-%s.csv", Sys.Date()),
    content = function(file) write_csv(trial(), file)
  )
  output$download_template <- shiny::downloadHandler(
    filename = "dtp-titecrm-template.csv",
    content = function(file) write_csv(example_trial_data(), file)
  )

  # --- Prior previews ----------------------------------------------------
  current_skeleton <- shiny::reactive({
    s <- settings()
    skeleton_from_settings(s$prior_type, s$target, s$halfwidth,
                           s$prior_mtd, s$num_doses, s$skeleton_text)
  })
  output$skeleton_preview <- shiny::renderUI({
    sk <- current_skeleton()
    if (!is.null(sk$problem)) {
      htmltools::div(class = "form-text text-danger mb-3", sk$problem)
    } else {
      htmltools::div(class = "form-text form-text-skeleton mb-3",
                     "Skeleton: ", paste(format(sk$skeleton, nsmall = 2),
                                         collapse = ", "))
    }
  })
  least_informative <- shiny::reactive({
    variance_from_settings("least_informative", NA,
                           current_skeleton()$skeleton, input$target)
  })
  output$variance_preview <- shiny::renderUI({
    shiny::req(input$variance_type == "least_informative")
    v <- least_informative()
    if (!is.null(v$problem)) {
      htmltools::div(class = "form-text text-danger mb-3", v$problem)
    } else if (!is.null(v$variance)) {
      htmltools::div(class = "form-text form-text-skeleton mb-3",
                     sprintf("Variance: %.3f, calculated from the skeleton.",
                             v$variance))
    }
  })
  # Start "Set my own" from the calculated value.
  shiny::observeEvent(input$variance_type, ignoreInit = TRUE, {
    v <- shiny::isolate(least_informative()$variance)
    if (input$variance_type == "own" && !is.null(v)) {
      shiny::updateNumericInput(session, "variance", value = round(v, 3))
    }
  })
  output$stop_prior_preview <- shiny::renderUI({
    p <- stopping_prior(input$stop_default_prior, input$stop_prior_mean,
                        input$stop_prior_ess, input$target)
    htmltools::div(
      class = if (is.null(p$problem)) "form-text" else
        "form-text text-danger",
      p$problem %||% sprintf("Be(%g, %g)", p$a, p$b)
    )
  })

  # --- Results -----------------------------------------------------------
  result <- shiny::reactiveVal()
  ran_with <- shiny::reactiveVal()
  shiny::observeEvent(input$run, ignoreNULL = FALSE, {
    snapshot <- list(settings = settings(), trial = trial())
    result(run_model(snapshot$settings, snapshot$trial))
    ran_with(snapshot)
  })

  output$stale_note <- shiny::renderUI({
    shiny::req(ran_with())
    if (!identical(ran_with(), list(settings = settings(), trial = trial()))) {
      htmltools::div(
        class = "small text-warning-emphasis mt-2",
        bsicons::bs_icon("exclamation-triangle"),
        "Settings or data changed since the last update."
      )
    }
  })

  fitted <- shiny::reactive({
    r <- result()
    shiny::req(r, length(r$problems) == 0)
    r
  })

  output$summary_boxes <- shiny::renderUI({
    r <- result()
    shiny::req(r)
    if (length(r$problems)) {
      return(problems_alert(r$problems,
                            "No recommendation: please fix the following."))
    }
    summary_boxes(r)
  })
  output$timeline_plot <- ggiraph::renderGirafe({
    r <- fitted()
    as_girafe(
      plot_timeline(r$data, r$settings$day_of_assessment,
                    r$settings$obswin, r$settings$num_doses, r$pathway),
      height = timeline_height(nrow(r$data) + 1)
    )
  })
  output$dose_toxicity_plot <- ggiraph::renderGirafe({
    r <- fitted()
    as_girafe(
      plot_dose_toxicity(r$pathway, r$skeleton, r$variance,
                         r$settings$target),
      height = dose_toxicity_height(r$pathway)
    )
  })
  output$model_table <- shiny::renderTable(
    format_model_table(model_table(fitted()$pathway)),
    striped = TRUE, hover = TRUE, width = "100%", align = "lcl"
  )
}

# Page layout (bslib, Bootstrap 5).
#
# Sidebar: an accordion with one panel per group of design settings, and
# the update button. Main: trial data, then the recommendation (value
# boxes) and a tabbed card with the plots and the model table.

#' Neutral light theme: system fonts, navy accent, ICR logo grey
app_theme <- function() {
  bslib::bs_theme(
    version = 5,
    bg = "#FFFFFF", fg = dtp_colours$ink,
    primary = dtp_colours$accent, secondary = dtp_colours$muted,
    base_font = bslib::font_collection(
      "system-ui", "-apple-system", "Segoe UI", "Roboto", "Helvetica Neue",
      "Arial", "sans-serif"
    ),
    "font-size-base" = "0.95rem",
    # Keep value-box icons beside the text down to narrow tiles (bslib
    # stacks them below 300px), so the three tiles stay short in one row.
    "bslib-value-box-horizontal-break-point" = "150px"
  ) |>
    bslib::bs_add_rules("
      .table, .handsontable { font-variant-numeric: tabular-nums; }
      .app-title img { height: 32px; }
      .accordion-button { font-weight: 600; }
      .form-text-skeleton { font-variant-numeric: tabular-nums; }
      /* fillable = FALSE leaves the main area a block, where bslib's gap
         spacing (which replaces card margins) has no effect. */
      .bslib-page-main.bslib-gap-spacing {
        display: flex; flex-direction: column;
      }
    ")
}

# Label with an info icon showing `help` on hover or focus.
with_help <- function(label, help) {
  htmltools::tagList(
    label, " ",
    bslib::tooltip(
      bsicons::bs_icon("info-circle", title = "Help",
                       class = "text-secondary"),
      help
    )
  )
}

design_panel <- function() {
  bslib::accordion_panel(
    "Design", value = "design", icon = bsicons::bs_icon("sliders"),
    shiny::sliderInput("num_doses", "Number of dose levels", min = 2,
                       max = 10, value = 5, step = 1, ticks = FALSE),
    shiny::sliderInput(
      "target",
      with_help("Target DLT rate",
                "The DLT probability the design aims for at the MTD."),
      min = 0.05, max = 0.5, value = 0.25, step = 0.01, ticks = FALSE
    ),
    shiny::numericInput(
      "obswin",
      with_help("DLT observation window (days)",
                "Each patient is followed for DLT for this many days, counting the entry day as day 1."),
      value = 30, min = 1, step = 1
    )
  )
}

prior_panel <- function() {
  bslib::accordion_panel(
    "Prior", value = "prior", icon = bsicons::bs_icon("graph-up"),
    shiny::radioButtons(
      "prior_type", "Prior DLT probabilities (skeleton)",
      choices = c("Calibrate" = "calibrate", "Enter my own" = "enter"),
      inline = TRUE
    ),
    shiny::conditionalPanel(
      "input.prior_type == 'calibrate'",
      shiny::sliderInput(
        "prior_mtd",
        with_help("Prior guess of the MTD (dose level)",
                  "The dose whose prior DLT probability equals the target."),
        min = 1, max = 5, value = 1, step = 1, ticks = FALSE
      ),
      shiny::numericInput(
        "halfwidth",
        with_help("Half-width of the indifference interval",
                  "Doses with DLT probability within target \u00b1 half-width are considered acceptable (Lee and Cheung, 2009). Defaults to a quarter of the target, and resets to it when the target changes."),
        value = 0.0625, min = 0.005, max = 0.25, step = 0.005
      )
    ),
    shiny::conditionalPanel(
      "input.prior_type == 'enter'",
      shiny::textInput(
        "skeleton_text", "One probability per dose, increasing",
        value = "0.03, 0.07, 0.20, 0.30, 0.40"
      )
    ),
    shiny::uiOutput("skeleton_preview"),
    shiny::radioButtons(
      "variance_type",
      with_help("Prior variance of the model parameter",
                "Empiric model: DLT probability = skeleton ^ exp(\u03b2), \u03b2 ~ N(0, variance). The least informative variance makes every dose about equally likely to be the MTD a priori (Lee and Cheung, 2011); a smaller variance gives a more informative prior."),
      choices = c("Least informative" = "least_informative",
                  "Set my own" = "own"),
      inline = TRUE
    ),
    shiny::conditionalPanel(
      "input.variance_type == 'own'",
      shiny::numericInput("variance", "Variance", value = 1, min = 0.01,
                          step = 0.05)
    ),
    shiny::uiOutput("variance_preview")
  )
}

rules_panel <- function() {
  bslib::accordion_panel(
    "Escalation rules", value = "rules",
    icon = bsicons::bs_icon("signpost-split"),
    bslib::input_switch("no_skip_esc",
                        "No skipping of untried doses when escalating",
                        value = TRUE),
    bslib::input_switch(
      "no_skip_deesc",
      with_help("No skipping of doses when de-escalating",
                "De-escalate at most one level below the last dose given."),
      value = TRUE
    ),
    bslib::input_switch(
      "global_coherence",
      with_help("No escalation above the target DLT rate",
                "Do not escalate if the observed DLT rate at the current dose is above the target."),
      value = TRUE
    )
  )
}

stopping_panel <- function() {
  bslib::accordion_panel(
    "Safety stopping", value = "stopping",
    icon = bsicons::bs_icon("sign-stop"),
    bslib::input_switch(
      "stop_on",
      with_help("Stop if the lowest dose is too toxic",
                "Beta-binomial rule: stop when P(DLT rate at dose 1 > target | data) exceeds the confidence level."),
      value = TRUE
    ),
    shiny::conditionalPanel(
      "input.stop_on",
      shiny::sliderInput("stop_confidence", "Confidence level", min = 0.5,
                         max = 0.99, value = 0.7, step = 0.01,
                         ticks = FALSE),
      shiny::numericInput(
        "stop_n_min",
        "Minimum patients at the lowest dose before stopping applies",
        value = 2, min = 0, step = 1
      ),
      bslib::input_switch(
        "stop_default_prior",
        "Weakly informative prior Be(target, 1 \u2212 target), effective sample size 1",
        value = TRUE
      ),
      shiny::conditionalPanel(
        "!input.stop_default_prior",
        bslib::layout_columns(
          shiny::numericInput("stop_prior_mean", "Prior mean DLT rate",
                              value = 0.2, min = 0.01, max = 0.99,
                              step = 0.05),
          shiny::numericInput("stop_prior_ess", "Effective sample size",
                              value = 10, min = 0.1, step = 1)
        )
      ),
      shiny::uiOutput("stop_prior_preview")
    )
  )
}

data_card <- function() {
  bslib::card(
    bslib::card_header(
      class = "d-flex align-items-center gap-2 flex-wrap",
      bsicons::bs_icon("table"), "Trial data",
      htmltools::div(
        class = "ms-auto d-flex gap-2",
        shiny::actionButton("add_patient", "Add patient",
                            icon = shiny::icon("plus"),
                            class = "btn-sm btn-outline-primary"),
        bslib::popover(
          shiny::actionButton("file_menu", "Files",
                              icon = shiny::icon("file-arrow-up"),
                              class = "btn-sm btn-outline-secondary"),
          title = "Load or save trial data",
          shiny::fileInput("upload", "Upload CSV or Excel",
                           accept = c(".csv", ".xlsx", ".xls")),
          htmltools::p(
            class = "small text-secondary",
            "Columns: dose, entry_day, status (Ongoing, Completed, DLT,",
            "Withdrawn), days_followed (for DLT and Withdrawn) and,",
            "optionally, evaluable (Yes or No; everyone is evaluable",
            "without it). The legacy app's five-column CSV is also accepted."
          ),
          htmltools::div(
            class = "d-flex flex-column gap-2",
            shiny::downloadButton("download_data", "Save current data",
                                  class = "btn-sm"),
            shiny::downloadButton("download_template", "Download template",
                                  class = "btn-sm btn-outline-secondary"),
            shiny::actionButton("load_example", "Load example data",
                                class = "btn-sm btn-outline-secondary")
          )
        )
      )
    ),
    bslib::card_body(
      bslib::layout_columns(
        col_widths = c(4, 8),
        shiny::numericInput(
          "day_of_assessment",
          with_help("Day of assessment",
                    "Study day of this analysis (T_A). Ongoing patients have been followed up to this day."),
          value = 50, min = 1, step = 1
        ),
        htmltools::p(
          class = "small text-secondary mb-0 align-self-center",
          "Edit cells directly; right-click a row to insert or remove it.",
          "Days followed are filled in for Ongoing and Completed patients.",
          "Untick Evaluable to leave a patient out of the model."
        )
      ),
      rhandsontable::rHandsontableOutput("grid", height = "auto"),
      shiny::uiOutput("data_problems")
    )
  )
}

results_tabs <- function() {
  bslib::navset_card_underline(
    full_screen = TRUE,
    bslib::nav_panel(
      "Dose transition pathway",
      ggiraph::girafeOutput("timeline_plot", height = "auto")
    ),
    bslib::nav_panel(
      "Dose–toxicity curves",
      ggiraph::girafeOutput("dose_toxicity_plot", height = "auto")
    ),
    bslib::nav_panel(
      "Model recommendations",
      shiny::tableOutput("model_table")
    )
  )
}

#' The app's page
app_ui <- function() {
  bslib::page_sidebar(
    title = htmltools::span(
      class = "app-title d-flex align-items-center gap-3",
      htmltools::img(src = "icr_logo.png",
                     alt = "The Institute of Cancer Research"),
      htmltools::span("TITE-CRM with Dose Transition Pathways")
